<script setup>
import {onMounted,ref} from 'vue'
import PageHeader from '../components/PageHeader.vue'
import GlassWindow from '../components/GlassWindow.vue'
import {api} from '../lib/api.js'
const segments=ref([]),nodes=ref([]),rights=ref([]),challenges=ref([]),error=ref(''),formOpen=ref(false),form=ref({name:'',nodeId:'',port:3389,accountSid:'',sourceIp:'',ttlMinutes:240,failOpen:false,mode:'agentless'})
async function load(){try{[segments.value,nodes.value,rights.value]=await Promise.all([api('/segments'),api('/nodes'),api('/logon-rights')]);const results=await Promise.all(segments.value.map(s=>api(`/segments/${s.id}/challenges`)));challenges.value=results.flat();error.value=''}catch(e){error.value=e.message}}
async function create(){try{await api('/segments',{method:'POST',body:form.value});formOpen.value=false;await load()}catch(e){error.value=e.message}}
async function baseline(nodeId){try{await api('/logon-rights/baseline',{method:'POST',body:{nodeId}});await load()}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><div class="view"><PageHeader eyebrow="IDENTITY / SEGMENTATION" title="Identity protection" description="Define MFA gates and inspect logon rights baselines"><button class="button primary" @click="formOpen=true"><i class="mdi mdi-plus"></i> New segment</button></PageHeader><div v-if="error" class="error-msg">{{error}}</div><section class="info-banner"><i class="mdi mdi-information-outline"></i><span>Agentless JIT enforcement requires a validated Windows connector and Entra setup. This build records segments and challenge decisions; rights mutation is disabled until validation.</span></section><div class="dashboard-grid"><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">POLICY GATES</span><h2>Segments</h2></div><span class="count-chip">{{segments.length}}</span></div><div v-for="segment in segments" :key="segment.id" class="segment-row"><div class="segment-icon"><i class="mdi mdi-shield-lock-outline"></i></div><div><strong>{{segment.name}}</strong><small>{{nodes.find(n=>n.id===segment.node_id)?.hostname||segment.node_id}} · TCP {{segment.port}} · {{segment.ttl_minutes}} min TTL</small></div><span class="status">{{segment.mode}}</span></div><div v-if="!segments.length" class="empty-side">No identity segments configured.</div></section><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">MFA TRAIL</span><h2>Challenges</h2></div><span class="count-chip">{{challenges.length}}</span></div><div v-for="challenge in challenges.slice(0,10)" :key="challenge.id" class="segment-row"><div class="segment-icon"><i class="mdi mdi-account-key-outline"></i></div><div><strong>{{challenge.user_upn}}</strong><small>{{new Date(challenge.challenged_at).toLocaleString()}}</small></div><span class="status" :class="challenge.status">{{challenge.status}}</span></div><div v-if="!challenges.length" class="empty-side">No MFA challenges recorded.</div></section></div><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">WINDOWS LSA</span><h2>Logon rights baseline</h2></div><select @change="baseline($event.target.value);$event.target.value=''" aria-label="Collect node baseline"><option value="">Collect from node…</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{node.hostname}}</option></select></div><div class="table-wrap"><table><thead><tr><th>NODE</th><th>ACCOUNT SID</th><th>LOGON TYPE</th><th>ASSIGNMENT</th><th>RECORDED</th></tr></thead><tbody><tr v-for="right in rights.slice(0,100)" :key="right.id"><td>{{nodes.find(n=>n.id===right.node_id)?.hostname||right.node_id}}</td><td class="mono">{{right.account_sid}}</td><td class="mono">{{right.logon_type}}</td><td>{{right.right_assignment}}</td><td>{{new Date(right.at).toLocaleString()}}</td></tr><tr v-if="!rights.length"><td colspan="5" class="empty-table">No baselines collected yet.</td></tr></tbody></table></div></section><GlassWindow v-model="formOpen" title="New identity segment"><form class="form-grid" @submit.prevent="create"><label>Name<input v-model="form.name" required placeholder="RDP to sensitive servers"></label><label>Target node<select v-model="form.nodeId" required><option value="">Select node</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{node.hostname}}</option></select></label><label>Target port<input v-model.number="form.port" type="number" min="1" max="65535" required></label><label>Account SID<input v-model="form.accountSid" placeholder="S-1-5-21-..."></label><label>Source IP/CIDR<input v-model="form.sourceIp" placeholder="10.0.0.0/8"></label><label>Grant TTL (minutes)<input v-model.number="form.ttlMinutes" type="number" min="1" max="10080"></label><label>Mode<select v-model="form.mode"><option value="agentless">Agentless</option><option value="agent">Agent</option></select></label><label class="check-label"><input v-model="form.failOpen" type="checkbox"> Fail open if MFA is unavailable</label><div class="form-actions"><button class="button primary">Create segment</button></div></form></GlassWindow></div></template>
